  public validacionNumeros(control: FormControl) {
    if (control.value == null) {
      return;
    }
    if (control.value.charAt(0) === " ") {
      control.setValue("");
    }

    for (let i = 0; i < control.value.length; i++) {

      if (isNaN(control.value.charAt(i))) {
        control.setValue(control.value.slice(0, control.value.length - 1));
      }

      if (control.value.length > 0 && control.value.charAt(i) === " ") {

        control.setValue(control.value.slice(0, control.value.length - 1));

      }

    }

    return null;

  }

  validacionTelefono(control: FormControl) {

    if (control.value == null && control.value != '') {
      return;
    }

    if (typeof control.value === 'string') {
      if (control.value.charAt(0) === " ") {
        control.setValue("");
      }
    }

    const caracteres = `!"#%&'()*/[]^_{|}~@QWERTYUIOPLKJHGFDSAZXCVBNMqwertyuiopasdfghjklzxcvbnm;<>?¿ª·=Ñ:¬-+`;


    for (let i = 0; i < control.value.length; i++) {

      if (caracteres.indexOf(control.value.charAt(i), 0) != -1) {
        control.setValue(control.value.slice(0, control.value.length - 1));
      }

      if (control.value.length > 0 && control.value.charAt(i) === " ") {

        control.setValue(control.value.slice(0, control.value.length - 1));

      }

    }
    return null;

  }




